func (m *MemStorage) SaveData(filePath string) error {
	fileData, err := m.marshalData()
	if err != nil {
		return err
	}

	return writeData(filePath, fileData)
}

func (m *MemStorage) marshalData() ([]byte, error) {
	data := map[string]interface{}{
		"gauges":   m.Gauges,
		"counters": m.Counters,
	}

	return json.Marshal(data)
}

func writeData(filePath string, fileData []byte) error {
	return os.WriteFile(filePath, fileData, 0644)
}

